package com.pricetrack.exchange.custody.proof;

import static com.pricetrack.exchange.custody.proof.CVaultTransactionProofModels.*;
import static com.pricetrack.exchange.custody.proof.CTransactionProofVerifierTest.*;
import static org.junit.jupiter.api.Assertions.*;
import com.pricetrack.exchange.custody.abi.*;
import com.pricetrack.exchange.custody.model.CCustodyModels;
import java.math.BigInteger;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.*;
import org.web3j.rlp.*;

/** Public deterministic fixture keys only. Assertions and snapshots are not actual RPC/canonical evidence. */
class CVaultTransactionProofVerifierTest {
    final CTransactionProofVerifierTest f=new CTransactionProofVerifierTest();
    final CVaultTransactionProofVerifier verifier=new CVaultTransactionProofVerifier();
    final CAbiCodec abi=new CAbiCodec();final CAbiEventCodec events=new CAbiEventCodec();
    Input cash(CAbiModels.VaultAction action,long amount){return cash(f.seed(2000),action,n(amount));}
    Input cash(CTransactionProofVerifierTest.Seed s,CAbiModels.VaultAction action,BigInteger amount){
        boolean withdraw=action==CAbiModels.VaultAction.WITHDRAW;List<CAbiEventModels.Log> logs=new ArrayList<>();
        logs.add(events.encode(TOKEN,new CAbiEventModels.Transfer(withdraw?VAULT:OWNER,withdraw?OWNER:VAULT,amount)));
        CAbiEventModels.Event e=switch(action){case DEPOSIT->new CAbiEventModels.Deposited(OWNER,amount);case WITHDRAW->new CAbiEventModels.Withdrawn(OWNER,amount);case FUND_HOUSE->new CAbiEventModels.HouseFunded(OWNER,amount);};
        logs.add(events.encode(VAULT,e));return fixture(s,new CAbiModels.VaultAmount(action,amount),logs,USER,withdraw?null:amount);
    }
    Input process(CTransactionProofVerifierTest.Seed s,ECKeyPair caller){
        List<CAbiEventModels.Log> logs=new ArrayList<>();if(s.vault().totalUnpaid().signum()>0&&s.vault().house().signum()>0){var claim=s.vault().claims().get(s.vault().head());var paid=claim.remaining().min(s.vault().house());logs.add(events.encode(VAULT,new CAbiEventModels.ProfitClaimPaid(s.vault().head(),claim.owner(),paid,claim.remaining().subtract(paid))));}
        return fixture(s,new CAbiModels.ProcessClaim(),logs,caller,null);
    }
    Input fixture(CTransactionProofVerifierTest.Seed s,CAbiModels.Call call,List<CAbiEventModels.Log> events,ECKeyPair key,BigInteger allowance){
        byte[] raw=raw(abi.encode(call),key);String hash=hex(Hash.sha3(raw));int index=s.vault().lastTransactionIndex()+1;List<CReceiptEnvelopeModels.RawLog> logs=new ArrayList<>();
        for(int j=0;j<events.size();j++){var e=events.get(j);logs.add(new CReceiptEnvelopeModels.RawLog(hash,n(1),h(101),n(index),n(index*10L+j),false,e.emitter(),e.topics(),e.data()));}
        var receipt=new CReceiptEnvelopeModels.Receipt(hash,n(1),h(101),n(index),addr(key),VAULT,1,logs);
        var envelope=new CReceiptEnvelopeModels.Input(hex(raw),hash,new CReceiptEnvelopeModels.Deployment(n(31337),TOKEN,VAULT,CONTROLLER,RULES),new CReceiptEnvelopeModels.BlockContext(n(1),h(101),n(1000)),receipt);
        var point=new CAuthorizationModels.ObservationPoint(n(1),h(101),hash,n(index));
        return new Input(envelope,new Context(point,s.vault(),s.token(),h(100),allowance==null?null:new AllowanceObservation(point,addr(key),VAULT,allowance)));
    }
    byte[] raw(String data,ECKeyPair key){List<RlpType> v=new ArrayList<>(List.of(r(n(7)),r(n(1)),r(n(1_000_000)),RlpString.create(bytes(VAULT)),r(n(0)),RlpString.create(bytes(data))));var unsigned=new ArrayList<>(v);unsigned.addAll(List.of(r(n(31337)),r(n(0)),r(n(0))));var sig=Sign.signMessage(Hash.sha3(RlpEncoder.encode(new RlpList(unsigned))),key,false);v.add(r(n(31337*2L+35+sig.getV()[0]-27)));v.add(r(new BigInteger(1,sig.getR())));v.add(r(new BigInteger(1,sig.getS())));return RlpEncoder.encode(new RlpList(v));}
    Result ok(Input i){var result=verifier.verify(i);assertEquals(Decision.VERIFIED_IN_SCOPE,result.decision(),result.reason());return result;}
    void deny(Input i){var result=verifier.verify(i);assertNotEquals(Decision.VERIFIED_IN_SCOPE,result.decision());assertNull(result.verified());}
    Input context(Input i,String field,Object value){return change(i,"context",change(i.context(),field,value));}
    Input log(Input i,int at,String field,Object value){var logs=new ArrayList<>(i.envelope().receipt().logs());logs.set(at,change(logs.get(at),field,value));return logs(i,logs);}
    Input logs(Input i,List<CReceiptEnvelopeModels.RawLog> logs){return change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"logs",logs)));}
    Input event(Input i,int at,CAbiEventModels.Event event){var old=i.envelope().receipt().logs().get(at);var encoded=events.encode(old.emitter(),event);return log(log(i,at,"topics",encoded.topics()),at,"data",encoded.data());}
    CTransactionProofVerifierTest.Seed funded(CTransactionProofVerifierTest.Seed s,long amount){return f.stage(s,new CCustodyModels.VaultCall(CCustodyModels.VaultAction.FUND_HOUSE,OWNER,n(amount)),OWNER,VAULT,List.of(TOKEN,VAULT),List.of(new CCustodyModels.Transfer(OWNER,VAULT,n(amount)),new CCustodyModels.HouseFunded(OWNER,n(amount))),List.of(new CAbiEventModels.Transfer(OWNER,VAULT,n(amount))));}
    CTransactionProofVerifierTest.Seed processed(CTransactionProofVerifierTest.Seed s){var r=ok(process(s,USER));return new CTransactionProofVerifierTest.Seed(r.verified().vault(),r.verified().token(),s.position());}
    @Test void depositCreditsOnlyRawSendersFreeAndMovesRealTokenSubset(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);var r=ok(i);assertEquals(n(3100),r.verified().vault().totalFree());assertEquals(n(5100),r.verified().vault().actualAssets());assertEquals(n(5100),r.verified().token().balanceOf(VAULT));assertEquals(i.context().token().balanceOf(OWNER).subtract(n(100)),r.verified().token().balanceOf(OWNER));}
    @Test void fundHouseCreditsNoUserFreeAndDoesNotPayClaims(){Input i=cash(f.waitingClaimWithHouse(),CAbiModels.VaultAction.FUND_HOUSE,n(100));var r=ok(i);assertEquals(i.context().vault().totalFree(),r.verified().vault().totalFree());assertEquals(n(200),r.verified().vault().house());assertEquals(n(950),r.verified().vault().totalUnpaid());}
    @Test void withdrawOwnFreeHasExactVaultAndWalletDeltas(){Input i=cash(CAbiModels.VaultAction.WITHDRAW,100);var r=ok(i);assertEquals(n(2900),r.verified().vault().totalFree());assertEquals(n(4900),r.verified().token().balanceOf(VAULT));assertEquals(i.context().token().balanceOf(OWNER).add(n(100)),r.verified().token().balanceOf(OWNER));}
    @Test void withdrawDoesNotRequireOrValidateIrrelevantAllowance(){Input i=cash(CAbiModels.VaultAction.WITHDRAW,100);ok(context(i,"allowance",new AllowanceObservation(null,null,null,null)));assertNull(i.context().allowance());}
    @Test void depositAndFundRequireCurrentPointAllowanceNotLastApprovalLog(){for(var action:List.of(CAbiModels.VaultAction.DEPOSIT,CAbiModels.VaultAction.FUND_HOUSE)){Input i=cash(action,100);assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"allowance",null)).decision());}}
    @Test void allowanceMissingFieldsOrWrongPointAndKeysAreInsufficient(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);for(String field:List.of("point","owner","spender","value"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"allowance",change(i.context().allowance(),field,null))).decision());for(String field:List.of("owner","spender"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,"allowance",change(i.context().allowance(),field,addr(ORACLE)))).decision());deny(context(i,"allowance",change(i.context().allowance(),"point",change(i.context().point(),"transactionIndex",n(99)))));}
    @Test void insufficientAllowanceIsRejectedAndUnlimitedIsAccepted(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);assertEquals("C_VTX_ALLOWANCE_AMOUNT",verifier.verify(context(i,"allowance",change(i.context().allowance(),"value",n(99)))).reason());var r=ok(context(i,"allowance",change(i.context().allowance(),"value",CAbiModels.UINT_MAX)));assertFalse(r.currentAllowanceVerified());}
    @Test void invalidAllowanceUintIsRejectedWithoutThrowableDetails(){Input i=cash(CAbiModels.VaultAction.FUND_HOUSE,100);deny(context(i,"allowance",change(i.context().allowance(),"value",n(-1))));deny(context(i,"allowance",change(i.context().allowance(),"value",CAbiModels.UINT_MAX.add(n(1)))));}
    @Test void zeroAmountAndWithdrawBeyondOwnFreeAreRejected(){deny(cash(CAbiModels.VaultAction.DEPOSIT,0));deny(cash(CAbiModels.VaultAction.WITHDRAW,3001));}
    @Test void transferFromAndToMustMatchRawOwnerAndVault(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(event(i,0,new CAbiEventModels.Transfer(addr(ORACLE),VAULT,n(100))));deny(event(i,0,new CAbiEventModels.Transfer(OWNER,addr(ORACLE),n(100))));}
    @Test void exactTransferAmountMustMatchCalldataAndVaultEvent(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(event(i,0,new CAbiEventModels.Transfer(OWNER,VAULT,n(99))));deny(event(i,1,new CAbiEventModels.Deposited(OWNER,n(101))));}
    @Test void withdrawCannotRedirectBeneficiaryOrInventADonation(){Input i=cash(CAbiModels.VaultAction.WITHDRAW,100);deny(event(i,0,new CAbiEventModels.Transfer(VAULT,addr(ORACLE),n(100))));deny(event(i,1,new CAbiEventModels.Withdrawn(addr(ORACLE),n(100))));}
    @Test void cashEventTypeEmitterOrderAndCountAreExact(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(event(i,1,new CAbiEventModels.HouseFunded(OWNER,n(100))));deny(log(i,1,"emitter",CONTROLLER));var list=new ArrayList<>(i.envelope().receipt().logs());Collections.swap(list,0,1);deny(logs(i,list));deny(logs(i,List.of(i.envelope().receipt().logs().getFirst())));}
    @Test void additionalApprovalIsNotExpectedWhenOZSpendsAllowance(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);var list=new ArrayList<>(i.envelope().receipt().logs());var old=list.getLast();var approval=events.encode(TOKEN,new CAbiEventModels.Approval(OWNER,VAULT,n(0)));list.add(new CReceiptEnvelopeModels.RawLog(old.transactionHash(),old.blockNumber(),old.blockHash(),old.transactionIndex(),old.logIndex().add(n(1)),false,TOKEN,approval.topics(),approval.data()));assertEquals("C_VTX_CASH_EVENT_COUNT",verifier.verify(logs(i,list)).reason());}
    @Test void processEmptyQueueHasNoEventsAndNoTokenTransfer(){var s=f.seed(2000);var r=ok(process(s,ORACLE));assertEquals(s.vault().balances(),r.verified().vault().balances());assertEquals(s.token().balances(),r.verified().token().balances());assertEquals(s.vault().house(),r.verified().vault().house());}
    @Test void processWithZeroHousePreservesClaimAndEmitsNothing(){var s=processed(f.waitingClaimWithHouse());assertEquals(n(0),s.vault().house());var r=ok(process(s,RELAY));assertEquals(s.vault().claims(),r.verified().vault().claims());assertEquals(s.vault().totalUnpaid(),r.verified().vault().totalUnpaid());}
    @Test void partialHeadPaymentCreditsFixedClaimOwnerNotPermissionlessCaller(){var s=f.waitingClaimWithHouse();var claim=s.vault().claims().get(n(1));var r=ok(process(s,USER));assertEquals(n(850),r.verified().vault().claims().get(n(1)).remaining());assertEquals(n(100),r.verified().vault().claims().get(n(1)).paid());assertEquals(s.vault().balances().get(claim.owner()).free().add(n(100)),r.verified().vault().balances().get(claim.owner()).free());assertEquals(s.vault().balances().get(OWNER),r.verified().vault().balances().get(OWNER));assertEquals(s.token().balances(),r.verified().token().balances());}
    @Test void fullyPaidHeadAdvancesExactlyOneAndKeepsClaimHistory(){var s=funded(f.waitingClaimWithHouse(),850);var r=ok(process(s,ORACLE));assertEquals(n(0),r.verified().vault().totalUnpaid());assertEquals(n(2),r.verified().vault().head());assertEquals(n(0),r.verified().vault().claims().get(n(1)).remaining());assertEquals(n(950),r.verified().vault().claims().get(n(1)).paid());}
    @Test void enoughHouseForTwoClaimsStillPaysOnlyTheFirst(){var s=f.waitingClaimWithHouse();var close=f.ok(f.fixture(s,4,n(11_000_000_000L),1000,true));s=new CTransactionProofVerifierTest.Seed(close.verified().vault(),close.verified().token(),close.verified().rules().after());s=funded(s,2000);var r=ok(process(s,RELAY));assertEquals(n(2),r.verified().vault().head());assertEquals(n(1000),r.verified().vault().claims().get(n(2)).remaining());assertEquals(n(0),r.verified().vault().claims().get(n(2)).paid());assertEquals(n(1150),r.verified().vault().house());}
    @Test void headOwnerIdPaidAndRemainingCannotBeChanged(){Input i=process(f.waitingClaimWithHouse(),USER);var l=i.envelope().receipt().logs().getFirst();var e=(CAbiEventModels.ProfitClaimPaid)events.decode(CAbiEventModels.EmitterKind.VAULT,new CAbiEventModels.Log(VAULT,l.topics(),l.data()));for(var field:e.getClass().getRecordComponents()){Object value=field(e,field.getName());deny(event(i,0,change(e,field.getName(),value instanceof BigInteger b?b.add(n(1)):OWNER)));}}
    @Test void processNoopCannotInventAPaymentAndFundedHeadCannotOmitIt(){Input empty=process(f.seed(2000),USER);var e=events.encode(VAULT,new CAbiEventModels.ProfitClaimPaid(n(1),OWNER,n(1),n(0)));deny(fixture(f.seed(2000),new CAbiModels.ProcessClaim(),List.of(e),USER,null));Input funded=process(f.waitingClaimWithHouse(),USER);deny(logs(funded,List.of()));ok(empty);}
    @Test void processCannotEmitATokenTransferOrMultipleHeadPayments(){Input i=process(f.waitingClaimWithHouse(),USER);deny(event(i,0,new CAbiEventModels.Transfer(OWNER,VAULT,n(0))));var list=new ArrayList<>(i.envelope().receipt().logs());list.add(change(list.getFirst(),"logIndex",list.getFirst().logIndex().add(n(1))));deny(logs(i,list));}
    @Test void revertedCashSkipsAllowanceAndHasNoFinancialEffects(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);i=logs(i,List.of());i=change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"status",0)));i=context(i,"allowance",null);var r=ok(i);assertTrue(r.verified().reverted());assertEquals(i.context().vault().balances(),r.verified().vault().balances());assertEquals(i.context().token().balances(),r.verified().token().balances());}
    @Test void revertedProcessWithLogsIsRejectedBeforeAccounting(){Input i=process(f.waitingClaimWithHouse(),USER);deny(change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"status",0))));}
    @Test void originalRawHashAndReceiptSenderCannotBeSubstituted(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(change(i,"envelope",change(i.envelope(),"expectedTransactionHash",h(99))));deny(change(i,"envelope",change(i.envelope(),"receipt",change(i.envelope().receipt(),"from",addr(ORACLE)))));}
    @Test void deploymentAndTokenIdentityCannotBeMixed(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(change(i,"envelope",change(i.envelope(),"deployment",change(i.envelope().deployment(),"vault",a(88)))));deny(context(i,"token",change(i.context().token(),"deployment",change(i.context().token().deployment(),"genesisHash",h(88)))));}
    @Test void missingContextExactPointAndCursorMismatchFailClosed(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);for(String field:List.of("point","vault","token","parentBlockHash"))assertEquals(Decision.INSUFFICIENT,verifier.verify(context(i,field,null)).decision());deny(context(i,"point",change(i.context().point(),"transactionHash",h(88))));deny(context(i,"token",change(i.context().token(),"lastTransactionIndex",n(1))));}
    @Test void envelopeResourceAndProjectionIntegerRangesStayBounded(){
        Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);
        Input excessiveLogs=logs(i,Collections.nCopies(129,i.envelope().receipt().logs().getFirst()));
        assertEquals(Decision.INSUFFICIENT,verifier.verify(excessiveLogs).decision());
        BigInteger huge=BigInteger.ONE.shiftLeft(80);i=logs(i,List.of());
        i=change(i,"envelope",change(change(i.envelope(),"receipt",change(change(i.envelope().receipt(),"blockNumber",huge),"status",0)),"block",change(i.envelope().block(),"number",huge)));
        i=context(i,"point",change(i.context().point(),"blockNumber",huge));
        assertEquals(Decision.UNSUPPORTED,verifier.verify(i).decision());
    }
    @Test void actualAssetsAndTokenSeedMustAgreeAndSecondReducerFailureIsAtomic(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);deny(context(i,"vault",change(i.context().vault(),"actualAssets",n(5001))));var balances=new HashMap<>(i.context().token().balances());balances.put(OWNER,balances.get(OWNER).subtract(n(1)));balances.put(a(88),n(1));deny(context(i,"token",change(i.context().token(),"balances",balances)));assertEquals(n(3000),i.context().vault().totalFree());}
    @Test void malformedOrUnsupportedCallCannotFabricateANoop(){Input base=process(f.seed(2000),USER);var unsupported=fixture(f.seed(2000),new CAbiModels.Cancel(n(0)),List.of(),USER,null);assertEquals(Decision.UNSUPPORTED,verifier.verify(unsupported).decision());ok(base);}
    @Test void checksumAddressesAndAllowanceKeysNormalizeWithoutChangingSignature(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);var ed=i.envelope().deployment();ed=change(change(change(change(ed,"token",upper(TOKEN)),"vault",upper(VAULT)),"controller",upper(CONTROLLER)),"rules",upper(RULES));i=change(i,"envelope",change(i.envelope(),"deployment",ed));i=context(i,"allowance",change(change(i.context().allowance(),"owner",upper(OWNER)),"spender",upper(VAULT)));ok(i);}
    @Test void repeatedPrestateIsDeterministicAndScopeDoesNotClaimCurrentAllowance(){Input i=cash(CAbiModels.VaultAction.DEPOSIT,100);var result=ok(i);assertEquals(result,ok(i));assertFalse(result.completeCoverage());assertFalse(result.currentAllowanceVerified());assertTrue(result.verificationScope().contains("PREVALIDATED_CONTEXT_ONLY"));assertFalse(i.toString().contains(i.envelope().rawSignedTransaction()));assertEquals(n(3000),i.context().vault().totalFree());}
}
